import{c as s,$ as r,Q as n,j as o,g as t,o as i,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const d="/img/en/front/workshop.webp",q=JSON.parse('{"title":"Equipment & Assets","description":"Universal management of equipment, machinery, tools, and depreciation calculation in OmniCraft ERP.","frontmatter":{"title":"Equipment & Assets","description":"Universal management of equipment, machinery, tools, and depreciation calculation in OmniCraft ERP.","datePublished":"2026-08-20","dateModified":"2026-11-25","order":1},"headers":[],"relativePath":"docs/resources/assets.md","filePath":"docs/resources/assets.md","lastUpdated":1795564800000}'),u={name:"docs/resources/assets.md"},h={id:"equipment-assets",tabindex:"-1"};function p(m,e,g,f,y,b){const a=r("DocIcon");return n(),o("div",null,[t("h1",h,[i(a,{name:"workshop"}),e[0]||(e[0]=l(" Equipment & Assets ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#equipment-assets","aria-label":'Permalink to "Equipment & Assets"'},"​",-1))]),e[2]||(e[2]=c('<figure class="doc-image craft-window-frame" data-title="Equipment and Assets — OmniCraft ERP"><img src="'+d+'" alt="Main window of Workshop (Equipment and Assets)"><figcaption>Main window of Workshop (Equipment and Assets)</figcaption></figure><p>The <strong>&quot;Workshop&quot;</strong> tab serves as the single command center for managing long-term physical assets across your business. Whether you handcraft products, run a repair and service center, manage retail inventory, or sell goods on marketplaces, your physical equipment forms the bedrock of your business net worth.</p><p>This is far more than a simple inventory list of tools on a shelf. The module connects tangible items directly with managerial accounting: it reveals the true current value of your business, calculates monthly wear and tear automatically, and helps you factor depreciation into your prices.</p><hr><h2 id="economic-principle-transforming-cash-into-capital-assets" tabindex="-1">Economic Principle: Transforming Cash into Capital Assets <a class="header-anchor" href="#economic-principle-transforming-cash-into-capital-assets" aria-label="Permalink to &quot;Economic Principle: Transforming Cash into Capital Assets&quot;">​</a></h2><p>In personal finance, purchasing expensive machinery is often viewed as spending money. In OmniCraft ERP&#39;s professional managerial accounting, acquiring production assets follows the law of capital preservation:</p><ol><li><strong>Capital does not decrease upon purchase.</strong> Spending $1,000 on a laser engraver, soldering station, or thermal printer does not make your business poorer. You simply convert liquid cash into a working fixed asset. Your total business net worth in the &quot;Capital&quot; report remains completely unchanged.</li><li><strong>Lean depreciation without machine-hour overhead.</strong> Enterprise accounting systems often force operators to log tedious machine-hours for every minor tool. OmniCraft ERP uses a streamlined straight-line depreciation method: <ul><li>The system divides historical cost by useful lifespan and computes the <strong>exact monthly depreciation across your entire workshop</strong>.</li><li>Knowing this figure alongside your average monthly output or service orders, you can factor equipment wear directly into your recipe overhead or labor rates. Equipment pays for itself predictably with every completed order.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Straight-line depreciation made simple</p><p>If an engraver is purchased for $1,200 with a 5-year useful life (60 months), the system reduces its book value by $20 each month. Your Capital balance always reflects honest, market-grounded value based on machine age rather than an inflated historical number.</p></div><hr><h2 id="two-tracking-modes-property-vs-consumables" tabindex="-1">Two Tracking Modes: Property vs Consumables <a class="header-anchor" href="#two-tracking-modes-property-vs-consumables" aria-label="Permalink to &quot;Two Tracking Modes: Property vs Consumables&quot;">​</a></h2><p>At the top of the workspace table, an intuitive switch lets you toggle between two fundamentally distinct types of physical assets:</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Property (Fixed Assets)</th><th style="width:50%;">Consumables (Workshop Tooling)</th></tr></thead><tbody><tr><td><strong>Category:</strong> Long-term capital equipment (machines, workbenches, vehicles).</td><td><strong>Category:</strong> Fast-wearing auxiliary tooling (drill bits, cutters, abrasive discs).</td></tr><tr><td><strong>Useful Lifespan:</strong> 1 to 20+ years (configured in item card).</td><td><strong>Useful Lifespan:</strong> None assigned (consumed in day-to-day operations).</td></tr><tr><td><strong>Balance Impact:</strong> Monthly linear depreciation into Net Worth.</td><td><strong>Balance Impact:</strong> Direct operational cash outflow in Cash Flow (DDS).</td></tr></tbody></table><h3 id="_1-long-term-property-fixed-assets" tabindex="-1">1. Long-term Property (Fixed Assets) <a class="header-anchor" href="#_1-long-term-property-fixed-assets" aria-label="Permalink to &quot;1. Long-term Property (Fixed Assets)&quot;">​</a></h3><p>Core equipment designed for years of productive life (machinery, workbenches, testing instruments, computers, commercial furniture, utility vehicles).</p><ul><li>Each item requires a designated <strong>useful lifespan</strong> in years or months.</li><li>The system deducts straight-line depreciation on a monthly cadence, gradually adjusting book value.</li><li>Remaining residual value feeds directly into the tangible asset block of your business Capital summary.</li></ul><h3 id="_2-consumables-fast-wearing-tooling" tabindex="-1">2. Consumables &amp; Fast-wearing Tooling <a class="header-anchor" href="#_2-consumables-fast-wearing-tooling" aria-label="Permalink to &quot;2. Consumables &amp; Fast-wearing Tooling&quot;">​</a></h3><p>Auxiliary tooling and attachments with short lifecycles (drill bits, CNC endmills, soldering tips, blades, brushes, specialty lubricants).</p><ul><li>Consumables <strong>do not carry a useful lifespan</strong> and do not accumulate depreciation.</li><li>Their acquisition cost posts immediately as an operating expense in the Cash Flow register (DDS) upon purchase.</li><li>Select <strong>&quot;Replenish (Buy more)&quot;</strong> in the asset card. Enter the date and fill in <strong>&quot;Purchase Amount&quot;</strong> or <strong>&quot;Shipping&quot;</strong>. If you paid both, fill in both fields. When saved, the amounts increase the consumable&#39;s book value, and purchase and shipping appear as separate Cash Flow entries.</li></ul><hr><h2 id="industry-specific-workflows" tabindex="-1">Industry-Specific Workflows <a class="header-anchor" href="#industry-specific-workflows" aria-label="Permalink to &quot;Industry-Specific Workflows&quot;">​</a></h2><p>The mechanics of logging and tracking assets are universal, but your daily operational focus depends on your business model:</p><h3 id="services" tabindex="-1">Service Centers &amp; Repair Studios <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Service Centers &amp; Repair Studios {#services}&quot;">​</a></h3><p>In a repair shop, service center, or customer studio, assets equip master technician workstations:</p><ul><li><strong>What to track under Property:</strong> diagnostic scanners, soldering stations, air compressors, vehicle lifts, sterilizers, professional salon stations, client waiting area furniture, and front-desk computers.</li><li><strong>What to track under Consumables:</strong> protective covers, disposable nozzles, solder wire, soldering iron tips, cleaning cloths, and contact cleaners.</li><li><strong>Depreciation recovery:</strong> divide total monthly equipment depreciation by your average monthly ticket count, factoring this cost directly into base hourly labor rates or fixed service premiums.</li></ul><h3 id="production" tabindex="-1">Manufacturing &amp; Craft Workshops <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Manufacturing &amp; Craft Workshops {#production}&quot;">​</a></h3><p>In artisanal and batch production shops, assets directly transform raw materials into finished merchandise:</p><ul><li><strong>What to track under Property:</strong> cutting tables, CNC laser engravers, industrial sewing machines, clicker presses, pottery kilns, and drying cabinets.</li><li><strong>What to track under Consumables:</strong> replacement rotary blades, heavy-duty needles, sanding disks, cutting mats, and polishing compounds.</li><li><strong>Depreciation recovery:</strong> in the &quot;Calculator&quot; module, include a machine wear allowance in product recipes so that every item sold reserves funds for future machinery replacement.</li></ul><h3 id="trade" tabindex="-1">Retailers &amp; E-commerce Marketplace Sellers <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;Retailers &amp; E-commerce Marketplace Sellers {#trade}&quot;">​</a></h3><p>In retail and fulfillment operations, assets streamline order packing, labeling, and stock movement:</p><ul><li><strong>What to track under Property:</strong> commercial barcode label printers, handheld laser scanners, impulse bag sealers, display shelving, pallet jacks, and digital parcel scales.</li><li><strong>What to track under Consumables:</strong> packing tape, bubble wrap rolls, poly mailers, and thermal shipping ribbons.</li><li><strong>Depreciation recovery:</strong> warehouse equipment depreciation is factored into order fulfillment and logistics overhead per dispatched parcel.</li></ul><hr><h2 id="asset-lifecycle-5-common-real-world-scenarios" tabindex="-1">Asset Lifecycle: 5 Common Real-World Scenarios <a class="header-anchor" href="#asset-lifecycle-5-common-real-world-scenarios" aria-label="Permalink to &quot;Asset Lifecycle: 5 Common Real-World Scenarios&quot;">​</a></h2><p>Clicking <strong>&quot;Add Asset&quot;</strong> opens the configuration dialog. Here is how to handle everyday asset operations without ledger confusion:</p><p>To record equipment through an external agent, enable Trusted Mode in <a href="./../global-settings">Global Settings</a>. Provide the asset name, category, purchase price and useful life. Enter delivery costs separately. Delivery is included in the asset value, and the purchase and delivery appear as separate expenses in cash flow.</p><h3 id="scenario-1-initial-setup-when-migrating-to-omnicraft" tabindex="-1">Scenario 1: Initial Setup When Migrating to OmniCraft <a class="header-anchor" href="#scenario-1-initial-setup-when-migrating-to-omnicraft" aria-label="Permalink to &quot;Scenario 1: Initial Setup When Migrating to OmniCraft&quot;">​</a></h3><p>You do not need to hunt down receipts from years ago. Estimate the machine&#39;s current fair market value by comparing used listings online, and assign its remaining expected lifespan (e.g., 3 years). The software calculates depreciation smoothly from that realistic baseline without distorting historical cash flow.</p><h3 id="scenario-2-personal-assets-transferred-in-or-equipment-grants" tabindex="-1">Scenario 2: Personal Assets Transferred In or Equipment Grants <a class="header-anchor" href="#scenario-2-personal-assets-transferred-in-or-equipment-grants" aria-label="Permalink to &quot;Scenario 2: Personal Assets Transferred In or Equipment Grants&quot;">​</a></h3><p>When you transfer personal tools into the business or receive subsidized government grant equipment:</p><ul><li>Enter the item&#39;s estimated value in the asset card.</li><li>Leave the cash account payment field empty (no deduction from Cash Flow).</li><li>The item appears on the balance sheet, increasing business net worth without recording a false cash deficit.</li></ul><h3 id="scenario-3-asset-revaluation-due-to-market-changes" tabindex="-1">Scenario 3: Asset Revaluation Due to Market Changes <a class="header-anchor" href="#scenario-3-asset-revaluation-due-to-market-changes" aria-label="Permalink to &quot;Scenario 3: Asset Revaluation Due to Market Changes&quot;">​</a></h3><p>If a machine&#39;s resale price changes, select <strong>&quot;Revalue&quot;</strong> in the asset card. Enter the new value, the effective date and the remaining useful life in years. Leave <strong>&quot;Paid maintenance / repair (expense in Cash Flow)&quot;</strong> unchecked and select <strong>&quot;Save&quot;</strong>. OmniCraft recalculates residual value and monthly depreciation from the revaluation date. No new Cash Flow entry is posted.</p><h3 id="scenario-4-routine-maintenance-vs-capital-upgrades" tabindex="-1">Scenario 4: Routine Maintenance vs Capital Upgrades <a class="header-anchor" href="#scenario-4-routine-maintenance-vs-capital-upgrades" aria-label="Permalink to &quot;Scenario 4: Routine Maintenance vs Capital Upgrades&quot;">​</a></h3><p>Always distinguish between operating maintenance and capital improvements:</p><ul><li><strong>Routine repairs and tune-ups (oil change, blade sharpening, drive belt replacement):</strong> record as a normal operating expense in Cash Flow under &quot;Equipment Maintenance&quot;. The machine&#39;s book value remains unchanged.</li><li><strong>Capital upgrades (for example, replacing a motor):</strong> select <strong>&quot;Revalue&quot;</strong> and enter the updated equipment values. To post the payment at the same time, select <strong>&quot;Paid maintenance / repair (expense in Cash Flow)&quot;</strong>, enter the amount paid and select <strong>&quot;Save&quot;</strong>. The equipment history shows the revaluation and Cash Flow shows the expense. If the payment is already posted, leave the checkbox unchecked.</li></ul><h3 id="scenario-5-archiving-and-restoring" tabindex="-1">Scenario 5: Archiving and Restoring <a class="header-anchor" href="#scenario-5-archiving-and-restoring" aria-label="Permalink to &quot;Scenario 5: Archiving and Restoring&quot;">​</a></h3><p>Select <strong>&quot;Send to Archive&quot;</strong> in the row or asset card. The card leaves the active list, and the equipment is excluded from workshop residual value and depreciation. Its history remains available.</p><p>To bring the card back, open <strong>&quot;Equipment Archive&quot;</strong> on the <strong>&quot;Fixed Assets&quot;</strong> tab or <strong>&quot;Consumables Archive&quot;</strong> on the <strong>&quot;Consumables&quot;</strong> tab and select <strong>&quot;Restore&quot;</strong>. If you sell equipment, record the proceeds in Cash Flow.</p><hr><h2 id="navigation-filters-registry-order" tabindex="-1">Navigation, Filters &amp; Registry Order <a class="header-anchor" href="#navigation-filters-registry-order" aria-label="Permalink to &quot;Navigation, Filters &amp; Registry Order&quot;">​</a></h2><p>When your tool inventory grows past dozens of items, leverage the top toolbar controls to maintain operational clarity:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Function</th><th style="text-align:left;">Practical Benefit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Search by Name</strong></td><td style="text-align:left;">Instant substring matching</td><td style="text-align:left;">Quickly locate tools by brand name, serial code, or model</td></tr><tr><td style="text-align:left;"><strong>Categories</strong></td><td style="text-align:left;">Group assets by functional type</td><td style="text-align:left;">Segment machines, hand tools, electronics, and furnishings</td></tr><tr><td style="text-align:left;"><strong>Locations</strong></td><td style="text-align:left;">Filter by physical workspace</td><td style="text-align:left;">Track equipment across the main floor, warehouse, or mobile vans</td></tr><tr><td style="text-align:left;"><strong>Column Sorting</strong></td><td style="text-align:left;">Sort by cost, date, or residual value</td><td style="text-align:left;">Identify high-value investments or machines nearing end of lifespan</td></tr><tr><td style="text-align:left;"><strong>Reset Filters</strong></td><td style="text-align:left;">One-click filter clear</td><td style="text-align:left;">Instantly restore full view of all active company assets</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Custom Categories &amp; Storage Locations</p><p>Click the pencil next to the category or storage location field to add, rename, or remove an entry in the current workspace. Renaming updates every linked card, including archived cards. Removing an entry clears the field on those cards. If the entry is in use, the app shows how many cards will be affected before you confirm.</p><p>An external agent can read the lists. To add, rename, or remove entries through the agent, enable trusted mode in <a href="./../global-settings">global settings</a>.</p></div><hr><h2 id="troubleshooting-common-pitfalls" tabindex="-1">Troubleshooting &amp; Common Pitfalls <a class="header-anchor" href="#troubleshooting-common-pitfalls" aria-label="Permalink to &quot;Troubleshooting &amp; Common Pitfalls&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">What should I do if machine depreciation calculates faster or slower than actual wear?</summary><div class="faq-content"><p>Open the machine card and adjust the estimated useful lifespan in months or salvage value. If necessary, execute a one-time revaluation entry to bring book value into alignment with current fair market valuation.</p></div></details><details class="faq-item"><summary class="faq-summary">Why does the system prevent deleting old machinery from the registry?</summary><div class="faq-content"><p>Direct deletion is locked if historical maintenance expenses or depreciation entries are logged against the asset. Open the asset card and select &quot;Write Off&quot; or &quot;Archive&quot; to preserve accounting balance sheet integrity.</p></div></details><details class="faq-item"><summary class="faq-summary">How do I record tools contributed from personal property before opening the shop?</summary><div class="faq-content"><p>Add the asset card using its historical acquisition date and current book value. Designate the financing source as founder equity—the machine will enter workshop assets without triggering a fictitious cash withdrawal from the operational register.</p></div></details></div>',55))])}const w=s(u,[["render",p]]);export{q as __pageData,w as default};
